module SPI_Slave_test_1 ( MOSI, SS_n, tx_data, tx_valid, clk, arst_n, MISO, 
        rx_data, rx_valid, test_si, test_so, test_se );
  input [7:0] tx_data;
  output [9:0] rx_data;
  input MOSI, SS_n, tx_valid, clk, arst_n, test_si, test_se;
  output MISO, rx_valid, test_so;
  wire   n56, n32, n34, n35, n36, n37, n38, n39, n40, n41, n43, n45, n46, n47,
         n49, n50, n52, n53, n54, n55, n3, n4, n5, n6, n26, n27, n28, n29, n33,
         n42, n48;
  wire   [1:0] CS;
  wire   [1:0] NS;
  wire   [3:2] rx_counter;

  NOR3X6M U27 ( .A(n41), .B(n35), .C(n48), .Y(n38) );
  XNOR2X8M U30 ( .A(rx_counter[2]), .B(n6), .Y(n39) );
  CLKBUFX2M U29 ( .A(n56), .Y(rx_valid) );
  NOR3X2M U31 ( .A(n32), .B(test_so), .C(n6), .Y(n56) );
  NOR2X2M U32 ( .A(n40), .B(n36), .Y(rx_data[1]) );
  NAND2X2M U33 ( .A(n38), .B(n4), .Y(n36) );
  CLKINVX2M U34 ( .A(n39), .Y(n42) );
  NOR2X2M U35 ( .A(n3), .B(n34), .Y(rx_data[9]) );
  NOR2X2M U36 ( .A(n40), .B(rx_counter[3]), .Y(n35) );
  CLKINVX2M U37 ( .A(n38), .Y(n29) );
  NOR2X4M U38 ( .A(n34), .B(n4), .Y(rx_data[8]) );
  NAND3X2M U39 ( .A(n28), .B(n35), .C(MOSI), .Y(n34) );
  NOR3X4M U41 ( .A(n36), .B(n42), .C(n6), .Y(rx_data[7]) );
  NOR3X4M U42 ( .A(n36), .B(n6), .C(n39), .Y(rx_data[3]) );
  NOR3X4M U43 ( .A(n4), .B(n40), .C(n29), .Y(rx_data[0]) );
  NOR3X4M U44 ( .A(n37), .B(n29), .C(n39), .Y(rx_data[2]) );
  NOR3X4M U45 ( .A(n37), .B(n42), .C(n29), .Y(rx_data[6]) );
  OAI22X1M U46 ( .A0(n26), .A1(SS_n), .B0(n27), .B1(SS_n), .Y(NS[1]) );
  NAND2X2M U47 ( .A(n42), .B(n6), .Y(n40) );
  CLKINVX2M U48 ( .A(n41), .Y(n28) );
  NOR3X4M U49 ( .A(n5), .B(n36), .C(n42), .Y(rx_data[5]) );
  AOI21X1M U51 ( .A0(n49), .A1(n50), .B0(SS_n), .Y(NS[0]) );
  OAI21X1M U53 ( .A0(MOSI), .A1(CS[1]), .B0(CS[0]), .Y(n49) );
  OAI21X1M U56 ( .A0(n5), .A1(rx_counter[2]), .B0(rx_counter[3]), .Y(n47) );
  CLKNAND2X4M U57 ( .A(n3), .B(n5), .Y(n37) );
  OAI32X2M U58 ( .A0(n4), .A1(n5), .A2(n41), .B0(n45), .B1(n6), .Y(n53) );
  OAI32X2M U60 ( .A0(n37), .A1(rx_counter[2]), .A2(n41), .B0(n43), .B1(n33), 
        .Y(n52) );
  NOR2X1M U62 ( .A(n41), .B(n3), .Y(n55) );
  NOR2X1M U63 ( .A(n46), .B(n41), .Y(n54) );
  AOI2B1X1M U64 ( .A1N(n37), .A0(rx_counter[2]), .B0(rx_counter[3]), .Y(n46)
         );
  SDFFSRX1M rx_counter_reg_3_ ( .D(n54), .SI(n33), .SE(test_se), .CK(clk), 
        .SN(1'b1), .RN(arst_n), .Q(rx_counter[3]), .QN(test_so) );
  SDFFSRX1M CS_reg_1_ ( .D(NS[1]), .SI(n26), .SE(test_se), .CK(clk), .SN(1'b1), 
        .RN(arst_n), .Q(CS[1]), .QN(n27) );
  SDFFSRX1M CS_reg_0_ ( .D(NS[0]), .SI(test_si), .SE(test_se), .CK(clk), .SN(
        1'b1), .RN(arst_n), .Q(CS[0]), .QN(n26) );
  SDFFSRX4M rx_counter_reg_1_ ( .D(n53), .SI(n4), .SE(test_se), .CK(clk), .SN(
        1'b1), .RN(arst_n), .Q(n5), .QN(n6) );
  SDFFSRX4M rx_counter_reg_0_ ( .D(n55), .SI(n27), .SE(test_se), .CK(clk), 
        .SN(1'b1), .RN(arst_n), .Q(n3), .QN(n4) );
  SDFFSRX2M rx_counter_reg_2_ ( .D(n52), .SI(n5), .SE(test_se), .CK(clk), .SN(
        1'b1), .RN(arst_n), .Q(rx_counter[2]), .QN(n33) );
  INVX2M U3 ( .A(1'b1), .Y(MISO) );
  INVXLM U8 ( .A(MOSI), .Y(n48) );
  NAND2X3M U9 ( .A(CS[1]), .B(n47), .Y(n41) );
  AND4X1M U10 ( .A(n38), .B(n3), .C(n39), .D(n6), .Y(rx_data[4]) );
  NAND3XLM U11 ( .A(n4), .B(n33), .C(CS[1]), .Y(n32) );
  NAND2XLM U12 ( .A(n26), .B(n27), .Y(n50) );
  NAND2XLM U13 ( .A(n28), .B(n4), .Y(n45) );
  NAND2XLM U14 ( .A(n28), .B(n37), .Y(n43) );
endmodule


